        fn.__module__ = handler.fn.__module__  # type: ignore
        fn.__qualname__ = handler.fn.__qualname__  # type: ignore
        return fn

    backend_vars = super().__getattribute__("_backend_vars")
    if name in backend_vars:
        value = backend_vars[name]
